  intel:['Assessed threat axis: 200 to 220 (Yemen).','Unconfirmed: AWACS reported low tracks near the Kuwait border on previous nights.'],
  dur:600, wcs:'TIGHT', adw:'YELLOW', mode:'MANUAL', ptl:210, axis:[210,335],
